[ApiController][Route("api/admin/queues")] public class QueueController : ControllerBase { private IQueueManagementService _s; public QueueController(IQueueManagementService s) => _s = s; [HttpGet("dashboard")] public async Task<IActionResult> Dashboard(CancellationToken ct) => Ok(await _s.GetDashboardAsync(ct)); [HttpPost("jobs/{id:guid}/retry")] public async Task<IActionResult> Retry(Guid id, CancellationToken ct) { await _s.RetryJobAsync(id, ct); return Ok(new { message = "Retry queued." }); } [HttpPost("jobs/{id:guid}/dead-letter")] public async Task<IActionResult> DeadLetter(Guid id, CancellationToken ct) { await _s.MoveToDeadLetterAsync(id, ct); return Ok(new { message = "Moved to dead-letter." }); } }

[ApiController][Route("api/events")] public class EventExplorerController : ControllerBase { private IEventExplorerService _s; public EventExplorerController(IEventExplorerService s) => _s = s; [HttpGet] public async Task<IActionResult> List([FromQuery] string? type, [FromQuery] string? aggregateId, CancellationToken ct) { var e = await _s.GetEventsAsync(type, aggregateId, null, null, ct); return Ok(new { total = e.Count, events = e }); } [HttpPost("{id:guid}/replay")] public async Task<IActionResult> Replay(Guid id, CancellationToken ct) { await _s.ReplayEventAsync(id, ct); return Ok(new { message = "Event replayed." }); } [HttpGet("schema/{eventType}")] public async Task<IActionResult> Schema(string eventType, CancellationToken ct) => Ok(await _s.GetSchemaAsync(eventType, ct)); }

